/* Live NiubiGEO question generation and evidence analysis. No credentials stored. */
names.research=['自动诊断与竞品分析','Research & competitor gaps'];
let geoGroup='discovery',geoPlanView=null;
let geoToken='',geoMarket=localStorage.getItem('signal-research-market')||'CN',geoState={runner:{profiles:[]},runs:[]},geoActive=null,geoTimer=null,geoTab='models';
let geoDraft={CN:{},US:{}};try{geoDraft={...geoDraft,...JSON.parse(localStorage.getItem('signal-research-drafts')||'{}')}}catch{}
for(const d of Object.values(geoDraft)){if(d.baselineVersion!==2){d.count='30';d.repeats='1';d.baselineVersion=2}}
const geoLocal=()=>['127.0.0.1','localhost'].includes(location.hostname)&&location.port==='8772';
const geoStage={queued:'等待执行',website:'读取官网',generating:'NiubiGEO 自动出题',sampling:'询问所选模型',report:'报告已生成'};
const geoStatus={queued:'等待中',running:'执行中',finished:'已完成',partial:'部分完成',failed:'失败',stopped:'已停止',interrupted:'曾中断'};
const geoKind={citation:'平台返回的引用',retrieved_source:'检索来源',answer_link:'回答中的普通链接'};
function geoCapture(){geoPlanView=null;const preview=$('#geo-plan');if(preview)preview.innerHTML='';const d=geoDraft[geoMarket]||={};for(const k of ['website','brand','skus','competitors','context','focus','count','repeats','generator','questions']){const e=$('#geo-'+k);if(e)d[k]=e.value}const box=$('#geo-models');if(box)d.providers=[...box.querySelectorAll('input:checked')].map(e=>e.value);localStorage.setItem('signal-research-drafts',JSON.stringify(geoDraft))}
async function geoFetch(path,body){if(!geoToken)throw Error('请先打开本机自动诊断执行器');const r=await fetch('/api/geo/'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+geoToken,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});const j=await r.json();if(!r.ok)throw Error(j.error||'执行器请求失败');return j}
function geoChange(m){geoCapture();geoMarket=m;localStorage.setItem('signal-research-market',m);geoActive=null;clearTimeout(geoTimer);render()}
function geoModel(pid){return geoActive?.config?.configuration?.[pid]?.name||geoState.runner.profiles.find(p=>p.id===pid)?.name||pid}
function geoOptions(){const d=geoDraft[geoMarket];return geoState.runner.profiles.filter(p=>p.markets.includes(geoMarket)).map(p=>`<option value="${esc(p.id)}" ${d.generator===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}
function geoPage(){const d=geoDraft[geoMarket]||{},running=geoActive&&['queued','running'].includes(geoActive.status);return `<div class="diag-hero"><div><div class="diag-eyebrow">NIUBIGEO · QUESTIONS → ANSWERS → EVIDENCE</div><h2>从官网到可追溯的 AI 可见度。</h2><p>自动出题、同题询问模型、比较品牌与 SKU、查看明确排名与引用来源。</p></div><a class="primary button" href="http://127.0.0.1:8772/#/w/demo/research" target="_blank" rel="noopener">打开本机自动诊断 ↗</a></div>${!geoLocal()?'<p class="notice">真实流程在本机执行器运行。请点击上方按钮；本页不生成演示分数。</p>':''}<div class="actions api-tabs"><button class="${geoMarket==='CN'?'primary':''}" onclick="geoChange('CN')">中国 · 中文问题</button><button class="${geoMarket==='US'?'primary':''}" onclick="geoChange('US')">美国 · English questions</button><button onclick="geoRefresh()">刷新模型与任务</button><a href="http://127.0.0.1:8771/#/w/demo/bai" target="_blank" rel="noopener">配置模型连接 ↗</a></div><section class="card"><div class="card-head"><h2>1 · 测量对象与题目范围</h2><span class="tag ${geoState.runner.configured?'badge':'warn'}">${geoState.runner.configured?'模型执行器已连接':'待连接模型'}</span></div><div class="grid"><div>${input('本市场官网或产品页','geo-website',d.website||'')}${input('品牌名与别名（| 分隔）','geo-brand',d.brand||'')}${area('SKU：每行 名称 | 精确别名 | 其他别名','geo-skus',d.skus||'')}${area('竞品：每行 品牌名 | 别名；域名可写在最后，以 ; 分隔','geo-competitors',d.competitors||'')}<p class="subtitle">例：玉兰油 | Olay ; olay.com.cn。SKU 与竞品仅用于分析，普通发现题会避免直接点名。</p></div><div>${area('官网补充背景：产品类别、功效、市场与人群','geo-context',d.context||'')}${input('希望覆盖的需求 / 场景','geo-focus',d.focus||'')}<div class="grid">${input('本市场不同题目数（默认 30）','geo-count',d.count||'30','number')}<p class="notice">同市场共用一组题目 · 每题问一次 · 每厂商一个固定模型</p></div><label for="geo-generator">出题模型（每 10 题一批）</label><select id="geo-generator" style="width:100%">${geoOptions()||'<option value="">请先配置本市场模型</option>'}</select><p class="subtitle">使用已固定版本的 NiubiGEO 出题与解析代码。题目是模型生成的候选问题，不代表用户真实使用量。官网内容仅作为背景，不计入可见度证据。</p></div></div></section><section class="card api-plan"><h2>2 · 选择回答模型</h2><div id="geo-models">${geoManufacturerControls(d)}</div><p class="notice">自动分批生成和去重；同市场各厂商共用同一题库，每题只问一次。大任务自动拆分，底层每次请求保持在接口限制内。不自动充值、不自动重试。无联网或平台未返回引用时，会如实显示无引用证据。</p><div class="actions"><button onclick="geoPreview()">查看调用计划（不调用模型）</button><button class="primary" ${geoToken&&!geoState.busy?'':'disabled'} onclick="geoStart(false)">自动出题并完成全流程</button><button ${geoToken&&!geoState.busy?'':'disabled'} onclick="geoGenerateOnly()">仅生成题目，先审核</button>${running?'<button onclick="geoStop()">停止后续调用</button>':''}</div><div id="geo-plan">${geoPlanMarkup()}</div><p id="geo-error" class="error" role="alert"></p></section><section class="card api-plan"><h2>可编辑题集</h2>${area('每行一道不同问题；可编辑去重后采样（最多 300 题）','geo-questions',d.questions||'')}<button ${geoToken&&!geoState.busy?'':'disabled'} onclick="geoStart(true)">用此题集询问所选模型</button></section><section class="card api-plan"><h2>任务与报告</h2><div class="actions">${geoState.runs.filter(r=>r.market===geoMarket).map(r=>`<button onclick="geoOpen('${r.id}')">${esc(r.brand)} · ${esc(r.created_at.slice(0,16))} · ${geoStatus[r.status]||esc(r.status)}</button>`).join('')||'<p class="muted">此市场尚无真实任务。</p>'}</div>${geoResult()}</section>`}
function geoRows(text,domains=false){return(text||'').split('\n').filter(x=>x.trim()).map(line=>{const [left,right='']=line.split(';');const a=left.split('|').map(s=>s.trim()).filter(Boolean);return{name:a[0],aliases:a,...(domains?{domains:right.split(',').map(s=>s.trim().toLowerCase()).filter(Boolean)}:{})}})}
function geoPayload(){geoCapture();const d=geoDraft[geoMarket];return{market:geoMarket,website:d.website||'',brand_aliases:(d.brand||'').split('|').map(s=>s.trim()).filter(Boolean),skus:geoRows(d.skus),competitors:geoRows(d.competitors,true),context:d.context||'',focus:d.focus||'',count:Number(d.count),repeats:1,generator:d.generator,providers:d.providers||[],prompts:(d.questions||'').split('\n').map(s=>s.trim()).filter(Boolean)}}
async function geoStart(manual,generateOnly=false){try{const body=geoPayload();if(manual)body.count=body.prompts.length;body.generate_only=generateOnly;const job=await geoFetch(manual?'sample':'start',body);geoActive=job;geoDraft[geoMarket].last=job.id;await geoRefresh(false);await geoOpen(job.id)}catch(e){if($('#geo-error'))$('#geo-error').textContent=e.message;else toast(e.message)}}
function geoGenerateOnly(){return geoStart(false,true)}
async function geoRefresh(capture=true){try{if(capture)geoCapture();if(geoToken)geoState=await geoFetch('state');if(page==='research')render()}catch(e){toast(e.message)}}
async function geoOpen(id){try{geoCapture();clearTimeout(geoTimer);const job=await geoFetch('run?id='+encodeURIComponent(id));if(job.config.market!==geoMarket)return;geoActive=job;if(job.prompts?.length&&geoDraft[geoMarket].loadedQuestions!==job.id+':'+job.prompts.length){geoDraft[geoMarket].questions=job.prompts.map(p=>p.text).join('\n');geoDraft[geoMarket].loadedQuestions=job.id+':'+job.prompts.length}await geoRefresh(false);if(['running','queued'].includes(job.status))geoTimer=setTimeout(()=>{if(page==='research')geoOpen(id)},2500)}catch(e){toast(e.message)}}
async function geoStop(){try{await geoFetch('stop',{id:geoActive.id});toast('将在当前调用完成后停止；已花费用与已完成证据保留')}catch(e){toast(e.message)}}
async function geoReanalyze(){try{const d=geoPayload();const j=await geoFetch('analyze',{id:geoActive.id,brand_aliases:d.brand_aliases,skus:d.skus,competitors:d.competitors});geoDraft[geoMarket].last=j.id;await geoOpen(j.id)}catch(e){toast(e.message)}}
async function geoExport(){try{downloadJSON(await geoFetch('export?id='+geoActive.id),'signal-geo-evidence-'+geoActive.id+'.json')}catch(e){toast(e.message)}}
function geoResult(){const j=geoActive;if(!j)return '';const r=j.report;return `<div class="notice"><b>${geoStage[j.stage]||esc(j.stage)} · ${geoStatus[j.status]||esc(j.status)}</b> · 回答已返回 ${j.samples.length} 条 · 调用计划上限 ${j.planned_max_calls} 次</div>${j.error?`<p class="error" role="alert">${esc(j.error)}</p>`:''}<p class="mono">${j.analysis_only?'重分析记录（未调用模型），原任务 '+esc(j.parent_run_id)+' · ':''}任务 ${esc(j.id)} · ${esc(j.config.website)} · ${esc(j.created_at)}</p>${j.website?.error?`<p class="notice">官网抓取失败，使用用户补充背景：${esc(j.website.error)}</p>`:''}${j.plan?'<p class="notice">冻结同一题库：'+j.prompts.length+' / '+j.plan.questions+' 道 · 出题批次 '+(j.generation_progress?.complete||0)+' / '+j.plan.generation_batches+' · 已尝试回答 '+j.samples.length+' / '+j.plan.answer_calls+'</p>':''}${j.prompt_hash?'<p class="mono">题库 SHA256 '+esc(j.prompt_hash)+'</p>':''}${['stopped','interrupted','partial','failed'].includes(j.status)&&j.prompt_hash?'<button onclick="geoResume()">核对检查点并继续未完成题目</button>':''}${j.generation?`<details><summary>自动出题来源与原始输出</summary><p>NiubiGEO 提交 ${esc(j.upstream?.commit||'')} · 出题模型 ${esc(geoModel(j.config.generator))}</p><pre class="evidence">${esc(j.generation.sample?.answer||j.generation.sample?.error||'无返回')}</pre></details>`:''}<div class="actions" style="margin:16px 0"><button onclick="geoExport()">↓ 导出完整证据包</button>${r?'<button onclick="geoReanalyze()">按当前 SKU / 竞品重新分析（不调用模型）</button>':''}${['models','gaps','sources','answers','coverage'].map((k,i)=>`<button class="${geoTab===k?'primary':''}" onclick="geoCapture();geoTab='${k}';render()">${['排名与 SKU','竞品覆盖缺口','引用分析','逐题原始回答','题库覆盖'][i]}</button>`).join('')}</div>${!r?'<p class="muted">尚无回答分析。生成失败或额度不足不会产生分数。</p>':geoReport(r,j)}<p class="subtitle">口径：分数为本批各题型分别统计的完整回答提及率；自然发现题排除已点名跟踪对象的题目。明确序号只表示本条回答列表位置；不推断情感，不代表全市场排名。API 回答来源与实际请求条件保存在证据包中。</p>`}
function geoReport(r,j){if(geoTab==='coverage')return geoCoverage(r,j);if(geoTab==='models')return geoGroupControls()+((r.groups?.[geoGroup]?.models)||r.models).map(m=>`<h3>${esc(geoModel(m.provider))}</h3><p>${m.eligible>0&&m.eligible<5?'<span class="tag warn">样本较少，仅用于试测</span> ':''}本题型有效样本 ${m.eligible} · 完整 ${m.complete} / 已尝试 ${m.attempted} · 计划 ${(r.groups?.[geoGroup]?.question_count??j.prompts.length)*j.config.repeats}</p>${table(['品牌','提及分','提及 / 有效','平均列表名次','有明确排名的样本','前三样本','被引用的回答'],m.brands.map(b=>`<tr><td>${esc(b.name)} ${b.own?'· 本品牌':''}</td><td>${b.score??'—'}</td><td>${b.mentions} / ${b.denominator}</td><td>${b.average_rank??'未给出排名'}</td><td>${b.ranked_samples}</td><td>${b.top3}</td><td>${b.citation_answers}</td></tr>`).join(''))}${m.skus.length?table(['SKU','提及分','提及 / 有效','平均列表名次','排名样本数'],m.skus.map(k=>`<tr><td>${esc(k.name)}</td><td>${k.score??'—'}</td><td>${k.mentions} / ${k.denominator}</td><td>${k.average_rank??'未给出排名'}</td><td>${k.ranked_samples}</td></tr>`).join('')):'<p class="muted">本次未配置 SKU。</p>'}`).join('');if(geoTab==='gaps')return `<p>仅筛选有效自然发现回答：竞品被提及或引用，而你的品牌既未被提及也未被引用。</p>${r.gaps.length?r.gaps.map(g=>`<div class="source"><div><b>${esc(g.prompt)}</b><p>${esc(geoModel(g.provider))} · 覆盖竞品：${esc(g.competitors.join('、'))}</p></div><button onclick="geoTab='answers';render();document.getElementById('${esc(g.sample_id)}')?.scrollIntoView()">查看回答证据</button></div>`).join(''):'<p class="muted">当前样本未发现符合条件的缺口；不代表全行业没有缺口。</p>'}`;if(geoTab==='sources')return `<p>引用、检索来源和回答普通链接分开统计；只有平台返回的引用进入品牌引用指标。</p>${r.sources.length?table(['来源域名','证据类型','归属','出现回答数','页面'],r.sources.map(s=>`<tr><td>${esc(s.domain)}</td><td>${geoKind[s.kind]}</td><td>${esc(s.owner)}</td><td>${s.answer_count}</td><td>${s.urls.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(u)} ↗</a>`).join('<br>')}</td></tr>`).join('')):'<p class="muted">平台未返回引用 / 检索来源，回答中也没有链接。不会把官网抓取内容当成回答引用。</p>'}`;return r.samples.map(s=>`<details class="api-answer" id="${esc(s.id)}"><summary>${esc(geoModel(s.provider))} · 问题 ${s.question_index+1} · 第 ${s.repeat} 次 · ${esc(s.status)}</summary><p><b>${esc(s.prompt)}</b></p><p>${s.analysis.eligible?'纳入自然发现评分':'未纳入自然发现评分（不完整或题目已点名跟踪对象）'}</p>${s.error?`<p class="error">${esc(s.error)}</p>`:`<pre class="evidence">${esc(s.answer)}</pre>`}${s.analysis.entities.filter(e=>e.alias).map(e=>`<p>${esc(e.name)}：${e.rank?'列表位置 '+e.rank.position+' · '+esc(e.rank.evidence):'已提及，未给出明确列表排名'}</p>`).join('')}<p class="mono">请求模型 ${esc(s.model_requested)} / 返回模型 ${esc(s.model_returned||'未返回')} · 联网请求 ${s.search_requested?'开':'关'} / 执行证据 ${s.search_observed?'有':'未确认'} · ${s.channel==='direct'?'厂商直连':'B.AI'} ${esc(s.protocol)} · sha256 ${esc(s.raw_sha256||'无原始返回')}</p>${s.analysis.citations.map(c=>`<p>${geoKind[c.kind]} · ${esc(c.owner)} · <a href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">${esc(c.url)}</a></p>`).join('')}</details>`).join('')}
const beforeResearchRender=render;render=function(){beforeResearchRender();if(page==='research'){$('#view').innerHTML=geoPage();document.querySelector('.page-head .actions').innerHTML='';document.querySelector('main > .notice').innerHTML='<span>真实运行记录 · 中国与美国分开测量 · 候选题目不冒充真实热度 · 原始回答与排名证据可导出。</span>';document.querySelector('.page-head .subtitle').textContent='输入官网，让出题、采样与证据分析在同一条流程完成。';const h=document.querySelector('header .actions > span');if(h)h.textContent=(geoActive?.config?.brand_aliases?.[0]||'自动诊断')+' / '+geoMarket;for(const e of document.querySelectorAll('#view input,#view textarea,#view select'))e.addEventListener('change',geoCapture)}};
async function geoLoad(){if(!geoLocal())return;try{const r=await fetch('/api/geo/session');if(!r.ok)throw Error('本机诊断配对失败');geoToken=(await r.json()).token;await geoRefresh(false);const id=geoDraft[geoMarket]?.last;if(id)await geoOpen(id)}catch(e){toast(e.message)}}
geoLoad();

function geoManufacturerControls(d){const groups={};for(const p of geoState.runner.profiles.filter(p=>p.markets.includes(geoMarket))){const key=p.manufacturer||p.model;(groups[key]||=[]).push(p)}return Object.entries(groups).map(([vendor,ps])=>`<div class="source"><div><b>${esc(vendor)}</b>${ps.map(p=>`<label style="display:block"><input type="radio" name="geo-vendor-${esc(vendor)}" value="${esc(p.id)}" ${(d.providers||[]).includes(p.id)?'checked':''}> ${esc(p.name)} · ${esc(p.model)} · ${p.search?'请求联网':'文本问答'}</label>`).join('')}</div><button onclick="this.closest('.source').querySelectorAll('input').forEach(e=>e.checked=false);geoCapture()">不测此厂商</button></div>`).join('')||'<p class="muted">先配置本市场模型，然后刷新。</p>'}
function geoGroupControls(){return '<div class="actions">'+[['discovery','自然发现'],['brand','品牌认知'],['comparison','品牌比较']].map(([k,v])=>`<button class="${geoGroup===k?'primary':''}" onclick="geoCapture();geoGroup='${k}';render()">${v}</button>`).join('')+'</div><p class="subtitle">三类题分开计算。仅所选固定模型代表本次厂商测试，不推断其全部模型或 App 表现。</p>'}
async function geoPreview(){try{const d=geoPayload();geoPlanView=await geoFetch('plan',d);$('#geo-plan').innerHTML=geoPlanMarkup()}catch(e){$('#geo-error').textContent=e.message}}
function geoPlanMarkup(){if(!geoPlanView)return '';const p=geoPlanView;return `<p class="notice">${p.questions} 道不同问题 × ${p.manufacturers} 家厂商 × 每题 1 次 = ${p.answer_calls} 次回答；另有 ${p.generation_calls} 次出题。计划最多 ${p.maximum_calls} 次。自然发现 ${p.families.discovery} / 品牌认知 ${p.families.brand} / 比较 ${p.families.comparison}。只查看计划不消耗模型额度。</p>`}
async function geoResume(){try{const j=await geoFetch('resume',{id:geoActive.id});await geoOpen(j.id)}catch(e){toast(e.message)}}
function geoCoverage(r,j){return `<h3>不同问题与执行覆盖</h3><p>题库 ${j.prompts.length} 道；已尝试 ${r.coverage?.attempted??j.samples.length} 次，完整 ${r.coverage?.complete??0} 次；计划 ${r.coverage?.planned_answers??'—'} 次。不同题目数与回答数分别统计。</p>${table(['题型','不同题目数'],Object.entries(r.groups||{}).map(([k,v])=>`<tr><td>${({discovery:'自然发现',brand:'品牌认知',comparison:'品牌比较'})[k]}</td><td>${v.question_count}</td></tr>`).join(''))}${table(['需求维度','题目数'],(r.dimensions||[]).map(d=>`<tr><td>${esc(d.label)}</td><td>${d.questions}</td></tr>`).join(''))}${Object.entries(j.blocked_models||{}).map(([p,e])=>`<p class="error">${esc(geoModel(p))} 后续调用已停止：${esc(e)}</p>`).join('')}<p class="subtitle">这是所生成题库的覆盖面，不是用户真实搜索频率；重复或不足的题库会保留供审核，不会自动补题花费。</p>`}
